protected void new(FormBuildControl _build, FormRun _formRun)
{
    super(_build, _formRun);
    this.setTemplateId('TFMHtmlButtonCtrl');
    this.setResourceBundleName('/Resources/html/TFMHtmlButtonCtrl');

    textProperty = this.addProperty(methodStr(TFMHtmlButtonCtrl, parmText), Types::String);
    faIconProperty = this.addProperty(methodStr(TFMHtmlButtonCtrl, parmFaIcon), Types::String);
    activeLayoutProperty = this.addProperty(methodStr(TFMHtmlButtonCtrl, parmActiveLayout), Types::String);
}

[FormPropertyAttribute(FormPropertyKind::Value, 'text', true)]
private str parmText(str _text = textProperty.parmValue())
{
    if(!prmisdefault(_text))
    {
        textProperty.setValueOrBinding(_text);
    }
    return textProperty.parmValue();
}

[FormPropertyAttribute(FormPropertyKind::Value, 'faicon', true)]
private str parmFaIcon(str _text = faIconProperty.parmValue())
{
    if(!prmisdefault(_text))
    {
        faIconProperty.setValueOrBinding(_text);
    }
    return faIconProperty.parmValue();
}

[FormPropertyAttribute(FormPropertyKind::Value, 'activelayout', true)]
private str parmActiveLayout(str _text = activeLayoutProperty.parmValue())
{
    if(!prmisdefault(_text))
    {
        activeLayoutProperty.setValueOrBinding(_text);
    }
    return activeLayoutProperty.parmValue();
}
